// Extract PDF links and data from ErateProfitWorks application page
const htmlContent = $input.item.json.data;
const applicationData = $input.item.json;

// Extract 470 Form PDF - Look specifically in the 470 Application # section
const form470Regex = /470 Application #[\s\S]*?href="(http:\/\/publicdata\.usac\.org\/EPC\/Prd\/Form470\/[^"]+\.pdf)"/i;
const form470Match = form470Regex.exec(htmlContent);

// Extract RFP Document(s) - Be very specific to avoid grabbing funding history PDFs
// Look for the RFP Document(s) section and stop before the next major section
const rfpRegex = /<div class="section full">\s*<div class="title">RFP Document\(s\)<\/div>\s*<div class="content">\s*<table>\s*<thead>[\s\S]*?<\/thead>\s*<tbody>([\s\S]*?)<\/tbody>\s*<\/table>\s*<\/div>\s*<\/div>/i;
const rfpSectionMatch = htmlContent.match(rfpRegex);
const rfpLinks = [];

if (rfpSectionMatch) {
  const rfpLinkRegex = /href="([^"]+\.pdf)"/gi;
  let match;
  while ((match = rfpLinkRegex.exec(rfpSectionMatch[1])) !== null) {
    // Only add links that look like RFP documents, not funding history
    const url = match[1];
    if (!url.includes('Form471') && !url.includes('Form470/2')) {
      rfpLinks.push(url);
    }
  }
}

// Extract equipment requirements from Category 2 Details table
const equipmentRegex = /<tbody>([\s\S]*?)<\/tbody>/gi;
const equipmentMatches = htmlContent.matchAll(equipmentRegex);
const equipment = [];

for (const tableMatch of equipmentMatches) {
  const rowRegex = /<tr>\s*<td>([^<]+)<\/td>\s*<td>([^<]+)<\/td>\s*<td>(\d+)<\/td>/gi;
  let rowMatch;

  while ((rowMatch = rowRegex.exec(tableMatch[1])) !== null) {
    equipment.push({
      function: rowMatch[1].trim(),
      manufacturer: rowMatch[2].trim(),
      quantity: parseInt(rowMatch[3])
    });
  }
}

// Extract contact info
const emailRegex = /mailto:([^?"]+)/gi;
const phoneRegex = /bt-phone[\s\S]*?>([^<]+)</gi;
const emails = [];
const phones = [];

let emailMatch;
while ((emailMatch = emailRegex.exec(htmlContent)) !== null) {
  if (!emails.includes(emailMatch[1])) {
    emails.push(emailMatch[1]);
  }
}

let phoneMatch;
while ((phoneMatch = phoneRegex.exec(htmlContent)) !== null) {
  const phone = phoneMatch[1].trim();
  if (phone !== '111-111-1111' && !phones.includes(phone)) {
    phones.push(phone);
  }
}

// Extract budget
const budgetRegex = /class="dollar"[^>]*>\$([^<]+)</i;
const budgetMatch = htmlContent.match(budgetRegex);
const budget = budgetMatch ? budgetMatch[1].trim() : null;

// Extract allowable contract date
const contractDateRegex = /Allowable Contract Date[\s\S]*?class="data"[^>]*>([^<]+)</i;
const contractDateMatch = htmlContent.match(contractDateRegex);
const contractDate = contractDateMatch ? contractDateMatch[1].trim() : null;

// Compile all PDFs to download
const pdfs = [];

if (form470Match) {
  pdfs.push({
    applicationNumber: applicationData.applicationNumber,
    pdfUrl: form470Match[1],
    fileName: `${applicationData.applicationNumber}_470_form.pdf`,
    type: '470'
  });
}

rfpLinks.forEach((url, index) => {
  pdfs.push({
    applicationNumber: applicationData.applicationNumber,
    pdfUrl: url,
    fileName: `${applicationData.applicationNumber}_rfp_${index + 1}.pdf`,
    type: 'RFP'
  });
});

// Add extracted structured data to first item
if (pdfs.length > 0) {
  pdfs[0].structuredData = {
    equipment: equipment,
    contacts: {
      emails: emails,
      phones: phones
    },
    budget: budget,
    contractDate: contractDate,
    applicantName: applicationData.applicantName,
    state: applicationData.state
  };
}

return pdfs.map(pdf => ({ json: pdf }));

// Prepare data for PDF analysis workflow
const items = $input.all();

return [{
  json: {
    applicationNumber: items[0].json.applicationNumber,
    applicantName: items[0].json.applicantName,
    state: items[0].json.state,
    products: items[0].json.products,
    pdfFiles: items.map(item => ({
      fileName: item.json.fileName,
      filePath: `/data/pdfs/${item.json.fileName}`,
      type: item.json.type
    }))
  }
}];
